module cpu_interface ( fast_clk, slow_clk, fast_rst_n, slow_rst_n, cpu_pc, 
        instruction, mem_addr, mem_wdata, mem_read_en, mem_write_en, mem_rdata, 
        mem_rvalid );
  output [11:0] cpu_pc;
  input [31:0] instruction;
  output [13:0] mem_addr;
  output [31:0] mem_wdata;
  input [31:0] mem_rdata;
  input fast_clk, slow_clk, fast_rst_n, slow_rst_n, mem_rvalid;
  output mem_read_en, mem_write_en;
  wire   cpu_ready, cpu_req, cpu_read_write, req_fifo_full, cache_req_en,
         cache_resp_en, resp_fifo_empty, req_fifo_r_en, req_fifo_empty,
         resp_fifo_w_en, resp_fifo_full;
  wire   [31:0] cpu_rdata;
  wire   [13:0] cpu_addr;
  wire   [31:0] cpu_wdata;
  wire   [46:0] cache_req_data;
  wire   [31:0] cache_resp_data;
  wire   [46:0] req_fifo_rdata;
  wire   [31:0] resp_fifo_wdata;

  cpu_core_PROG_ADDR_WIDTH12_DATA_ADDR_WIDTH14_DATA_WIDTH32 u_cpu_core ( .clk(
        fast_clk), .rst_n(fast_rst_n), .instruction(instruction), .pc(cpu_pc), 
        .rdata(cpu_rdata), .cpu_ready(cpu_ready), .cpu_req(cpu_req), 
        .read_write(cpu_read_write), .addr(cpu_addr), .wdata(cpu_wdata) );
  cache_ADDR_WIDTH14_DATA_WIDTH32_CACHE_LINES8_WORDS_PER4 u_cache ( .clk(
        fast_clk), .rst_n(fast_rst_n), .cpu_req(cpu_req), .read_write(
        cpu_read_write), .addr(cpu_addr), .wdata(cpu_wdata), .rdata(cpu_rdata), 
        .cpu_ready(cpu_ready), .fifo_req_full(req_fifo_full), .fifo_req_data(
        cache_req_data), .fifo_req_en(cache_req_en), .fifo_resp_en(
        cache_resp_en), .fifo_resp_data(cache_resp_data), .fifo_resp_empty(
        resp_fifo_empty) );
  async_fifo_WIDTH47_DEPTH4 u_request_fifo ( .rclk(slow_clk), .wclk(fast_clk), 
        .w_rst_n(fast_rst_n), .r_rst_n(slow_rst_n), .r_data(req_fifo_rdata), 
        .w_data(cache_req_data), .r_en(req_fifo_r_en), .w_en(cache_req_en), 
        .full(req_fifo_full), .empty(req_fifo_empty) );
  async_fifo_WIDTH32_DEPTH4 u_response_fifo ( .rclk(fast_clk), .wclk(slow_clk), 
        .w_rst_n(slow_rst_n), .r_rst_n(fast_rst_n), .r_data(cache_resp_data), 
        .w_data(resp_fifo_wdata), .r_en(cache_resp_en), .w_en(resp_fifo_w_en), 
        .full(resp_fifo_full), .empty(resp_fifo_empty) );
  memory_controller_ADDR_WIDTH14_DATA_WIDTH32 u_memory_controller ( .clk(
        slow_clk), .rst_n(slow_rst_n), .req_data(req_fifo_rdata), .req_empty(
        req_fifo_empty), .req_en(req_fifo_r_en), .resp_data(resp_fifo_wdata), 
        .resp_en(resp_fifo_w_en), .resp_full(resp_fifo_full), .mem_addr(
        mem_addr), .mem_wdata(mem_wdata), .mem_read_en(mem_read_en), 
